/**
 * Native dashboards in the console's model — what
 * dashboardsApi.ts maps control-plane `DashboardService` into.
 *
 * A HYBRID of two kinds a reader can open, plus a gallery:
 *
 *   release     generated by forge, or declared in the repo
 *               (deploy/observability/dashboards). Code, so read-only here;
 *               "Save as copy" forks one into the workspace.
 *   workspace   authored in the console: saved in place, versioned (author,
 *               message, history, restore), promotable to code.
 *   template    a built-in starting point; SaveAsCopy instantiates it.
 *
 * The spec a dashboard carries is forge's (`forge.dashboards/v1`, the
 * `Dashboard` of types.ts). The server validates and canonicalizes it on every
 * write, so the console sends what it edited and never serializes a file of
 * its own.
 */

import type { Dashboard } from "./types";

/**
 * Where a dashboard lives. `generated` and `repo` are both release dashboards
 * (one addressing space on the server); they differ only in who wrote them.
 */
export type DashboardSource = "generated" | "repo" | "workspace" | "template" | "builtin";

/** The three addressing spaces: what a URL has to name to find a dashboard again. */
export type DashboardKind = "release" | "workspace" | "template" | "builtin";

export function kindOfSource(source: DashboardSource): DashboardKind {
  return source === "generated" || source === "repo" ? "release" : source;
}

export interface DashboardRef {
  kind: DashboardKind;
  /** The forge project ("" = project-less). */
  projectId: string;
  /** A release dashboard's id, a workspace dashboard's slug, a template's id. */
  key: string;
}

export interface DashboardUser {
  id: string;
  name: string;
  email: string;
}

export interface DashboardReleaseInfo {
  /** The release whose bundle carried it (the newest promotion that did). */
  releaseVersion: string;
  shippedAtMs: number | null;
  /** Repo dashboards: where the file lives. */
  filePath: string;
  /** The environments whose CURRENT release carries it. */
  envIds: string[];
}

export interface DashboardWorkspaceInfo {
  version: number;
  createdBy: DashboardUser | null;
  updatedBy: DashboardUser | null;
  createdAtMs: number | null;
  updatedAtMs: number | null;
  /** "release:<id>", "template:<id>" or "workspace:<slug>"; empty when started blank. */
  forkedFrom: string;
  /** The environments it is about. Empty: every environment. */
  envIds: string[];
}

/** One row of the index. Never a full spec. */
export interface DashboardSummary {
  /**
   * Absent/standard: spec renderer. The rest are typed built-in views:
   * organization-costs, organization-usage and organization-billing over
   * control-plane BillingService; llm-usage over reliant's own usage
   * (clientBuiltins.ts).
   */
  viewKind?: "standard" | "organization-costs" | "organization-usage" | "organization-billing" | "llm-usage";
  ref: DashboardRef;
  source: DashboardSource;
  title: string;
  description: string;
  readOnly: boolean;
  /** Per caller. */
  starred: boolean;
  /** Per caller; null when never viewed. */
  lastViewedAtMs: number | null;
  panelCount: number;
  /** Up to three headline panels (forge panel objects) a card draws as sparklines. */
  previewPanels: Dashboard["panels"];
  release: DashboardReleaseInfo | null;
  workspace: DashboardWorkspaceInfo | null;
  /** Templates: "generated" or "platform". */
  category: string;
  /**
   * The page group the spec declares (overview, services, jobs, product,
   * platform, releases, custom), defaulted by the server. Absent from a
   * control plane that predates it: the page infers one (dashboardGroups.ts).
   */
  group?: string;
  /** The spec's tags (lowercase, at most eight); search matches them. */
  tags?: string[];
}

export interface DashboardIndex {
  dashboards: DashboardSummary[];
  /** The caller may author (admin): New, Save and Save as copy are disabled otherwise. */
  canWrite: boolean;
}

export interface DashboardDocument {
  summary: DashboardSummary;
  spec: Dashboard;
  /** The workspace version returned; 0 for a release dashboard or template. */
  version: number;
  canWrite: boolean;
}

export interface DashboardVersion {
  /** A workspace version; 0 for a release entry. */
  version: number;
  /** A release entry: the release in which the content last changed. */
  releaseVersion: string;
  author: DashboardUser | null;
  message: string;
  createdAtMs: number | null;
  current: boolean;
}

export interface SavedDashboard {
  summary: DashboardSummary;
  version: DashboardVersion;
}

/** Which environments a dashboard is about. An empty list is every environment. */
export interface EnvScopeInput {
  envIds: string[];
}

export interface ListDashboardsInput {
  orgId: string;
  projectId?: string;
  envId?: string;
}

export interface GetDashboardInput {
  orgId: string;
  ref: DashboardRef;
  /** Workspace: an older version. */
  version?: number;
  /** Release: as shipped in this release. */
  releaseVersion?: string;
}

export interface SaveDashboardInput {
  orgId: string;
  projectId: string;
  slug: string;
  spec: Dashboard;
  /** Absent: unchanged on an update, every environment on a create. */
  envScope?: EnvScopeInput;
  /** 0 creates; N updates and must equal the current version. */
  baseVersion: number;
  message: string;
}

export interface SaveAsCopyInput {
  orgId: string;
  from: DashboardRef;
  projectId?: string;
  /** Empty: derived from the source's key. */
  slug?: string;
  /** Empty: the source's title. */
  title?: string;
  envScope?: EnvScopeInput;
  message?: string;
}

export interface PromotedDashboard {
  /** deploy/observability/dashboards/<slug>.json */
  path: string;
  /** The file, exactly as forge writes it. */
  content: string;
  /** The pull request, once the GitHub path is wired; empty until then. */
  prUrl: string;
  warnings: string[];
}
